-- RF-10: initial preventive contents, two per category, so the learning center and the AI tutor
-- have real material from day one. Fixed ids so they are the same in every environment.
-- Titles and bodies are user-facing, so they stay in Spanish.
INSERT INTO content (id, title, body, category_id) VALUES
    ('10000000-0000-0000-0000-000000000001',
     'Conoce las rutas de evacuación y los puntos de encuentro',
     'Antes de que ocurra una emergencia, identifica las rutas de evacuación y los puntos de encuentro de tu edificio. Ubica al menos dos salidas desde los lugares donde pasas más tiempo y recorre el camino hasta el punto de encuentro. Observa la señalización verde y los planos de evacuación de cada piso. Conocer el camino de antemano te permite actuar con calma cuando no hay tiempo para pensar.',
     '00000000-0000-0000-0000-000000000001'),
    ('10000000-0000-0000-0000-000000000002',
     'Prepara tus contactos de emergencia y tu kit básico',
     'Ten a la mano una lista de contactos de emergencia, tanto personales como institucionales, guardada en tu celular y en un papel. Mantén un kit básico con linterna, pilas, silbato, botiquín y agua. Acuerda con tu familia dónde se encontrarían si no pueden comunicarse. Revisa el kit cada seis meses para reemplazar lo vencido.',
     '00000000-0000-0000-0000-000000000001'),

    ('10000000-0000-0000-0000-000000000003',
     'Qué hacer durante un sismo si estás en un espacio cerrado',
     'Mantén la calma y no corras hacia la salida. Agáchate, cúbrete debajo de una mesa resistente o junto a una pared interna y sujétate hasta que el movimiento termine. Aléjate de ventanas, vidrios, lámparas y estantes que puedan caer. No uses los ascensores. Cuando el temblor pare, espera las indicaciones de los brigadistas y evacua con orden.',
     '00000000-0000-0000-0000-000000000002'),
    ('10000000-0000-0000-0000-000000000004',
     'Qué hacer durante un sismo si estás en un espacio abierto',
     'Si estás al aire libre, aléjate de edificios, postes, cables eléctricos, árboles y fachadas que puedan desprenderse. Ubícate en una zona despejada, agáchate y protege tu cabeza y cuello con los brazos. No entres a los edificios mientras dure el temblor. Mantente en el lugar hasta que el movimiento se detenga por completo.',
     '00000000-0000-0000-0000-000000000002'),

    ('10000000-0000-0000-0000-000000000005',
     'Primeras acciones después de un sismo',
     'Cuando el movimiento termine, revisa si tú o las personas cercanas tienen lesiones y avisa a los brigadistas. No muevas a quien tenga una lesión grave salvo que haya peligro inmediato. Ten en cuenta que pueden presentarse réplicas. No uses fósforos ni encendedores por posibles fugas de gas, y atiende siempre las instrucciones de brigadistas y coordinadores.',
     '00000000-0000-0000-0000-000000000003'),
    ('10000000-0000-0000-0000-000000000006',
     'Réplicas y regreso a las instalaciones',
     'Después de un sismo fuerte pueden ocurrir réplicas durante horas o días. Si te encuentras dentro de un edificio, repite las acciones de protección: agacharte, cubrirte y sujetarte. No reingreses a las instalaciones hasta que los responsables lo autoricen. Reporta grietas, daños en la estructura, fugas o cables caídos a los brigadistas o al personal de seguridad.',
     '00000000-0000-0000-0000-000000000003'),

    ('10000000-0000-0000-0000-000000000007',
     'Cómo evacuar con orden',
     'Al recibir la orden de evacuar, camina sin correr, sin empujar y sin devolverte por objetos personales. Usa las escaleras y nunca el ascensor. Mantén la derecha y deja libre el paso para quienes necesiten apoyo. Sigue la señalización de evacuación y las indicaciones de los brigadistas hasta llegar al punto de encuentro.',
     '00000000-0000-0000-0000-000000000004'),
    ('10000000-0000-0000-0000-000000000008',
     'El punto de encuentro y el conteo de personas',
     'Una vez en el punto de encuentro, permanece con tu grupo y repórtate con el docente, coordinador o brigadista a cargo para que te incluyan en el conteo. No regreses al edificio por ningún motivo hasta que se autorice. Si sabes que alguien quedó atrás o necesita ayuda, informa a los brigadistas en lugar de volver a buscarlo.',
     '00000000-0000-0000-0000-000000000004'),

    ('10000000-0000-0000-0000-000000000009',
     'Seguridad en laboratorios ante una emergencia',
     'Si ocurre una emergencia en un laboratorio, detén lo que estás haciendo, apaga los equipos que puedas hacerlo de forma segura y cierra las llaves de gas y los recipientes con reactivos. Luego evacua con orden siguiendo la ruta señalizada. Conoce la ubicación de las duchas de emergencia, los lavaojos y los extintores antes de empezar a trabajar.',
     '00000000-0000-0000-0000-000000000005'),
    ('10000000-0000-0000-0000-000000000010',
     'Qué hacer ante un derrame o una fuga de sustancias',
     'Si se derrama o se fuga una sustancia, avisa de inmediato al responsable del laboratorio y a los brigadistas. No intentes limpiarla si no tienes el entrenamiento ni los elementos de protección adecuados. Aléjate de la zona, ventila si es posible hacerlo sin riesgo y no permitas que otras personas se acerquen hasta que el personal autorizado indique que es seguro.',
     '00000000-0000-0000-0000-000000000005'),

    ('10000000-0000-0000-0000-000000000011',
     'Qué hacer en un salón de clase durante una emergencia',
     'Si estás en un salón, protégete debajo de tu mesa o junto a una pared interna y aléjate de las ventanas. Sigue las instrucciones del docente. Cuando termine el movimiento o se dé la orden, evacúa en orden junto con tu grupo, sin correr y sin llevar objetos voluminosos. El docente debe verificar que nadie quede en el salón.',
     '00000000-0000-0000-0000-000000000006'),
    ('10000000-0000-0000-0000-000000000012',
     'Mantén libres las salidas y los pasillos del salón',
     'Mantén los pasillos y las puertas del salón libres de mochilas, sillas y otros objetos que puedan estorbar durante una evacuación. Identifica las dos salidas más cercanas desde tu puesto y la ruta hacia el punto de encuentro. Informa al personal de la universidad si ves una salida bloqueada o mobiliario que pueda caer.',
     '00000000-0000-0000-0000-000000000006'),

    ('10000000-0000-0000-0000-000000000013',
     'Cómo evacuar un auditorio',
     'En un auditorio hay mucha gente reunida, por eso es clave mantener la calma. No corras hacia la puerta principal: usa todas las salidas señalizadas y avanza en fila. Agáchate y cúbrete entre las filas de sillas si el movimiento aún no termina. Sigue las instrucciones de los brigadistas y del personal del evento, y deja libres los pasillos para quienes necesiten apoyo.',
     '00000000-0000-0000-0000-000000000007'),
    ('10000000-0000-0000-0000-000000000014',
     'Prevención en auditorios: salidas libres y aforo',
     'Antes de cada evento, verifica que las salidas de emergencia estén libres y sin llave, que los pasillos no tengan sillas adicionales y que no se supere el aforo permitido. Identifica la ubicación de las salidas apenas ingreses. Los organizadores deben designar responsables que guíen la evacuación y conozcan el punto de encuentro.',
     '00000000-0000-0000-0000-000000000007'),

    ('10000000-0000-0000-0000-000000000015',
     'Protégete en tu puesto de trabajo durante un sismo',
     'Si estás en una oficina, agáchate y cúbrete debajo del escritorio, sujétate de él y aléjate de ventanas, archivadores y estantes. No uses el ascensor. Cuando termine el movimiento, evacúa por las escaleras siguiendo la ruta señalizada y las indicaciones de los brigadistas, sin llevarte objetos que retrasen tu salida.',
     '00000000-0000-0000-0000-000000000008'),
    ('10000000-0000-0000-0000-000000000016',
     'Orden preventivo en la oficina',
     'Asegura los archivadores y estantes altos para que no se vuelquen, evita guardar objetos pesados en la parte superior y mantén libres los pasillos y las salidas. Desconecta los equipos que no uses y no sobrecargues las tomas eléctricas. Conoce quiénes son los brigadistas de tu piso y cuál es el punto de encuentro de tu edificio.',
     '00000000-0000-0000-0000-000000000008');
